const NOTICE = 'You have a new secure message. Sign in to the portal to read it.';

/** Generic notification (no names, subject or body). Failures are logged by id/code only. */
async function notifyRecipient(messageId: string, recipientId: string, email: string): Promise<void> {
  const errCode = (e: unknown) => (e as { code?: string } | null)?.code ?? 'unknown';
  try {
    await sendMail({
      to: email,
      subject: 'New secure message',
      text: `${NOTICE}\n\n${env.appBaseUrl}`,
    });
  } catch (e) {
    logger.error('message mail failed', { messageId, code: errCode(e) });
  }
  try {
    const tokens = await listPushTokens(recipientId);
    for (const token of tokens) {
      try {
        await sendPush({
          token,
          notification: { title: 'New secure message', body: 'Sign in to the portal to read it.' },
        });
      } catch (e) {
        logger.error('message push failed', { messageId, code: errCode(e) });
      }
    }
  } catch (e) {
    logger.error('message push lookup failed', { messageId, code: errCode(e) });
  }
}
